package com.otgflasher.pro;import android.app.Activity;import android.os.Bundle;import android.widget.*;import java.io.*;public class SaharaActivity extends Activity{TextView txtDetail,log;ProgressBar bar;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_sahara);txtDetail=findViewById(R.id.txt_detail);log=findViewById(R.id.log_view);bar=findViewById(R.id.progress_bar);findViewById(R.id.btn_back).setOnClickListener(v->finish());findViewById(R.id.btn_sahara_test_0).setOnClickListener(v->run("edl --loader=/sdcard/Download/prog_firehose_ddr.elf --memory=ufs --sahara"));
findViewById(R.id.btn_diag_enable_1).setOnClickListener(v->run("adb shell setprop sys.usb.config diag,adb"));
findViewById(R.id.btn_root_magisk_2).setOnClickListener(v->run("python3 /sdcard/Download/magisk_patch.py /sdcard/Download/boot.img"));
findViewById(R.id.btn_flash_twrp_3).setOnClickListener(v->run("fastboot flash recovery /sdcard/Download/twrp.img"));
findViewById(R.id.btn_brom_bypass_4).setOnClickListener(v->run("python3 -m mtk payload"));
}void run(String c){bar.setProgress(5);log.append("\n> "+c+"\n");new Thread(()->{try{Process p=Runtime.getRuntime().exec(new String[]{"sh","-c",c+" 2>&1"});BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()));String l;int pr=5;while((l=r.readLine())!=null){pr+=2;if(pr>95)pr=95;String ll=l;int pp=pr;runOnUiThread(()->{bar.setProgress(pp);txtDetail.setText(pp+"% "+ll);log.append(ll+"\n");});}p.waitFor();runOnUiThread(()->bar.setProgress(100));}catch(Exception e){runOnUiThread(()->log.append("ERR "+e.getMessage()+"\n"));}}).start();}}